84	    (SG_TUNED_GEMM_IMPL != SG_GEMM_IMPL_WGMMA)
85	#error "SG_TUNED_GEMM_IMPL must be SG_GEMM_IMPL_SCALAR (0) or SG_GEMM_IMPL_WGMMA (1)"
86	#endif
87	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
88	#include "csrc/fused/sm_90/model_stage_mamba_tc.cuh"
89	#endif
