91	namespace sg { namespace fused { namespace sm90 {
92	
93	// Compile-time guard: the byte budget the launcher uses (kMambaSmemBytes) MUST
94	// equal sizeof(MambaSampleSmem). model_stage_mamba3.cuh already static_asserts
95	// the same equality (it pins kMambaSmemFloats to the actual struct); we restate
96	// it here so this header is self-contained and a drift fails loudly at this TU.
97	static_assert((int64_t)sizeof(MambaSampleSmem) == kMambaSmemBytes,
98	              "fused_mamba_megakernel: sizeof(MambaSampleSmem) != the documented "
99	              "kMambaSmemBytes in mamba3_layout.cuh — update kMambaSmemFloats.");
100	
101	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
102	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
103	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
104	// under a mamba_ name so this header stays self-contained — the decoder file is
105	// owned by a sibling agent and must not be included.)
106	template <OptId Opt>
107	__device__ __forceinline__ FusedOptState
108	mamba_rebase_state(const FusedOptState& s, int64_t off) {
109	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
110	    if (t.exp_avg)    t.exp_avg    += off;
111	    if (t.exp_avg_sq) t.exp_avg_sq += off;
112	    if (t.ema)        t.ema        += off;
113	    if (t.sam_dir)    t.sam_dir    += off;
114	    if (t.s_track)    t.s_track    += off;
115	    if (t.mu)         t.mu         += off;
116	    if (t.orth)       t.orth       += off;
117	    if (t.smart_grad) t.smart_grad += off;
118	    return t;
119	}
120	
121	// The L3-REAL Mamba megakernel needs the int TOKEN path + a grad-partial
122	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
123	// fused_megakernel) so the surrogate path is untouched. MambaTokenCtx mirrors the
124	// decoder's DecoderTokenCtx (int tokens, NOT ViT's float patches).
125	//
126	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
127	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
128	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
129	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
130	// total == kMambaTotalElems == 259425.
131	struct MambaTokenCtx {
132	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
133	    const int* targets;  // [B]       int32 target ids in [0, kPHead)
134	    int        B;        // batch size
135	    float*     workspace; // grad partials + loss partials + reduced loss
136	    float*     loss_out;  // device float the kernel writes the mean loss into
137	};
138	
139	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
140	//    threads/CTA. MambaSampleSmem (~141.72 KB) lives in DYNAMIC smem (extern). ──
141	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
142	// __constant__ tables kMambaSizes/kMambaOffsets (mamba3_layout.cuh), read directly
143	// by the reduce + optimizer phases.
144	template <OptId Opt>
145	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
146	fused_mamba_megakernel(PersistentContext ctx,
147	                       float* __restrict__ params,
148	                       MambaTokenCtx tok,
149	                       float* __restrict__ grad,        // reduced grad [total]
150	                       float lr, int step, FusedOptState st) {
151	    extern __shared__ char mamba_smem_raw[];
152	    MambaSampleSmem& sm = *reinterpret_cast<MambaSampleSmem*>(mamba_smem_raw);
153	    GridBarrier bar = ctx.barrier();
154	    const int cta = blockIdx.x;
155	    const int nCTA = (int)ctx.n_ctas;
156	    const int64_t total = kMambaTotalElems;
157	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
158	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
159	
160	    // NO warp-group register repartition here (UNLIKE the decoder/vit seams).
161	    // The decoder/vit copy a §3.4 producer/consumer setmaxnreg (dealloc<32> on
162	    // warpgroup 0, alloc<200> on warpgroup 1) — valid ONLY when warpgroup 0 needs
163	    // few registers. Mamba is NOT warp-specialized that way: ALL 256 threads do
164	    // SYMMETRIC selective-scan work, each thread owning a channel j∈[0,256) and
165	    // holding large register-resident scan state (fwd A[16]+h[16]; bwd adds
166	    // hh[kSeq+1][kState]+a_save[kSeq][kState]+dB_loc/dC_loc[kSeq][kState]+gh+dA),
167	    // so a dealloc<32> would spill it. __launch_bounds__(SG_TUNED_MEGA_BLOCK) sets the uniform
168	    // budget; the compiler allocates symmetrically across all 256 threads.
169	
170	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
171	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
172	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
173	    bar.sync();   // B0
174	
175	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
176	    MambaWeights w = mb_bind(params);
177	    MambaGrad g = mb_bind_grad(my_partial);
178	    const int B = tok.B;
179	    const int base = B / nCTA, rem = B % nCTA;
180	    const int b0 = cta * base + (cta < rem ? cta : rem);
181	    const int cnt = base + (cta < rem ? 1 : 0);
182	    const int b1 = b0 + cnt;
183	    __shared__ int tok_s[mb::kSeq];   // this sample's token ids (broadcast)
184	    __shared__ int tgt_s;
185	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
186	    for (int b = b0; b < b1; ++b) {
187	        if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
188	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
189	        __syncthreads();
190	        float nll = mb_forward_sample(w, tok_s, tgt_s, &sm);
191	        mb_backward_sample(w, g, tok_s, tgt_s, B, &sm);
192	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
193	        __syncthreads();   // sample boundary: all grad writes done before reuse
194	    }
195	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
196	    bar.sync();   // B1: all CTA partials + loss slots complete
197	
198	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
199	    //    (one task = one parameter tensor; sum its elements across CTAs in
200	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
201	    //    deterministic regardless of which CTA grabs the task. ─────────────────
202	    {
203	        __shared__ int task_slot;
204	        TaskQueue q = ctx.queue();
205	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
206	             t = q.next_block(&task_slot)) {
207	            const int n = kMambaSizes[t];
208	            const int64_t off = (int64_t)kMambaOffsets[t];
209	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
210	                float acc = 0.0f;
211	                for (int c = 0; c < nCTA; ++c)
212	                    acc += tok.workspace[(int64_t)c * total + off + i];
213	                grad[off + i] = acc;
214	            }
215	        }
216	    }
217	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
218	    // tightest gate; fp32 atomic-summing many terms can miss it.
219	    if (cta == 0 && threadIdx.x == 0) {
220	        double s = 0.0;
221	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
222	        float mean = (float)(s / (double)B);
223	        *tok.loss_out = mean;
224	    }
225	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
226	
227	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 28
228	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
229	    st.lr = lr;
230	    {
231	        __shared__ int task_slot;
232	        TaskQueue q = ctx.queue();
233	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
234	             t = q.next_block(&task_slot)) {
235	            const int n = kMambaSizes[t];
236	            const int64_t off = (int64_t)kMambaOffsets[t];
237	            const FusedOptState ts = mamba_rebase_state<Opt>(st, off);
238	            float* __restrict__ p = params + off;
239	            const float* __restrict__ gg = grad + off;
240	            for (int i = threadIdx.x; i < n; i += blockDim.x)
241	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
242	        }
243	    }
244	}
245	
246	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
247	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
248	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the Mamba footprint requires
249	//    (exactly as launch_fused_vit_megakernel does):
250	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, kMambaSmemBytes)
251	//      (2) dynamicSMemBytes = kMambaSmemBytes in the occ≥1 query
252	//      (3) dynamicSMemBytes = kMambaSmemBytes at <<<...>>>
253	//    All three are mandatory; missing any one makes the launch silently fail. ───
254	template <OptId Opt>
255	cudaError_t launch_fused_mamba_megakernel(
256	        PersistentContext ctx, float* params, MambaTokenCtx tok,
257	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
258	    int dev = 0;
259	    cudaError_t err = cudaGetDevice(&dev);
260	    if (err != cudaSuccess) return err;
261	    int n_sms = 0;
262	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
263	    if (err != cudaSuccess) return err;
264	
265	    const int dyn_smem = (int)kMambaSmemBytes;   // 145124 B (≈141.72 KB)
266	
267	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
268	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
269	    err = cudaFuncSetAttribute(
270	        (const void*)&fused_mamba_megakernel<Opt>,
271	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
272	    if (err != cudaSuccess) return err;
273	
274	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
275	    int occ = 0;
276	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
277	        &occ, (const void*)&fused_mamba_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
278	        /*dynamicSMemBytes=*/dyn_smem);
279	    if (err != cudaSuccess) return err;
280	    // At least one CTA per SM must be resident or the grid barrier can never be
281	    // satisfied. ~141.72 KB dynamic smem fits the sm_90 ~227 KB cap at occ=1 (the
282	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
283	    // block/SM, REFUSE rather than hang.
284	    assert(occ >= 1 &&
285	           "fused_mamba_megakernel: 0 blocks/SM — GridBarrier would hang. The "
286	           "Mamba per-sample smem (~142KB dynamic) + regs exceed one-block-per-SM "
287	           "occupancy on this device; reduce footprint or fall back to eager.");
288	    if (occ < 1) return cudaErrorLaunchOutOfResources;
289	
290	    const unsigned launch_ctas = (unsigned)n_sms;
291	    ctx.n_ctas = launch_ctas;
292	
293	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
294	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
295	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
296	
297	    // (3) Launch WITH the dynamic-smem byte count.
298	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
299	    fused_mamba_megakernel<Opt><<<grid, block, dyn_smem, stream>>>(
300	        ctx, params, tok, grad, lr, step, st);
301	    return cudaGetLastError();
302	}
303	
304	// ════════════════════════════════════════════════════════════════════════════
305	//  WGMMA CELL DRIVER (Fork B, R2 Mamba TC). Compiled only under the wgmma token;
306	//  the scalar path above is untouched. UNLIKE the scalar Mamba megakernel, this
307	//  uses STATIC smem (the per-(layer,sample) activation cache lives in HBM tile-
308	//  scratch, NOT smem — so NO dynamic-smem opt-in; the decoder TC launcher's
309	//  contract, not the scalar mamba launcher's three-step opt-in).
310	// ════════════════════════════════════════════════════════════════════════════
311	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
312	
313	// TC megakernel threads: 256 (the scan owns channels 0..255; the wgmma is
314	// warpgroup-scoped on threads 0..127). No asymmetric setmaxnreg.
315	#define SG_MB_TC_MEGA_BLOCK 256
316	
317	// ── Static smem arena: one A(64×16) + one B(N×16) bf16 tile + the 256-float
318	//    reduction slot + the scan-bwd cross-channel reduce targets (dBmat/dCmat,
319	//    [kSeq×kState] each) + the 8 dW specs (shared, not per-thread stack). ──
320	struct MbTcSmem {
321	    __nv_bfloat16 sA[64 * 16];
322	    __nv_bfloat16 sB[SG_TUNED_TILE_N * 16];
323	    float red[256];
324	    float dBmat[mb::kSeq * mb::kState];
325	    float dCmat[mb::kSeq * mb::kState];
326	    mbtc::MbDwSpec spec[8];
327	};
328	
329	// TC workspace layout (carved from tok.workspace; host sizes it):
330	//   [0 .. acts_f)                          : MbActs bf16 region
331	//   [acts_f .. + nCTA*scratch)             : per-CTA tile scratch (f32)
332	//   [.. + nCTA*kPartElems)                 : per-CTA non-GEMM grad partials (f32)
333	//   [.. + nCTA)                            : per-CTA loss slots
334	//   [.. + 1)                               : reduced scalar loss
335	__host__ __device__ __forceinline__ int64_t mb_tc_acts_floats(int T) {
336	    return mbtc::mb_acts_floats(T);
337	}
338	__host__ __device__ __forceinline__ int64_t mb_tc_workspace_floats(int T, int nCTA) {
339	    return mb_tc_acts_floats(T)
340	         + (int64_t)nCTA * mbtc::mb_tile_scratch_floats()
341	         + (int64_t)nCTA * mbtc::kPartElems
342	         + nCTA + 1;
343	}
344	
345	template <OptId Opt>
346	__global__ void __launch_bounds__(SG_MB_TC_MEGA_BLOCK)
347	fused_mamba_megakernel_tc(PersistentContext ctx,
348	                          float* __restrict__ params,
349	                          MambaTokenCtx tok,
350	                          float* __restrict__ grad,
351	                          float lr, int step, FusedOptState st) {
352	    __shared__ MbTcSmem sm;
353	    GridBarrier bar = ctx.barrier();
354	    const int cta = blockIdx.x;
355	    const int nCTA = (int)ctx.n_ctas;
356	    const int B = tok.B;
357	    const int T = B * mb::kSeq;
358	
359	    // Workspace partition.
360	    float* ws = tok.workspace;
361	    const int64_t acts_f = mb_tc_acts_floats(T);
362	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
363	    float* scratch_base = ws + acts_f;
364	    const int64_t scratch_per = mbtc::mb_tile_scratch_floats();
365	    float* part_base = scratch_base + (int64_t)nCTA * scratch_per;
366	    float* loss_part = part_base + (int64_t)nCTA * mbtc::kPartElems;
367	    float* loss_out  = loss_part + nCTA;
368	
369	    mbtc::MbActs acts = mbtc::mb_acts_bind(acts_base, T);
370	    mbtc::MbTileScratch sc = mbtc::mb_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
371	    float* my_part = part_base + (int64_t)cta * mbtc::kPartElems;
372	    mbtc::MbPartial part = mbtc::mb_partial_bind(my_part);
373	
374	    MambaWeights w = mb_bind(params);
375	
376	    // ── P0: zero this CTA's non-GEMM grad partial + loss slot. ──
377	    for (int64_t i = threadIdx.x; i < mbtc::kPartElems; i += blockDim.x) my_part[i] = 0.0f;
378	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
379	    bar.sync();   // B0
380	
381	    // ── P1: sample-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
382	    //    kTileM rows; fwd (→ acts X, NLL) then bwd (→ acts dY, dh0, partial). ──
383	    const int nrows_tile = mbtc::kTileM;
384	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
385	    float nll_acc = 0.0f;
386	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
387	        const int g0 = ti * nrows_tile;
388	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
389	        float nll = mbtc::mbtc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
390	                                            sm.sA, sm.sB, sm.red);
391	        mbtc::mbtc_backward_tile(w, g0, nrows, B, acts, sc, part, tok.tokens, tok.targets,
392	                                 sm.sA, sm.sB, sm.red, sm.dBmat, sm.dCmat);
393	        if (threadIdx.x == 0) nll_acc += nll;
394	        __syncthreads();
395	    }
396	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
397	    bar.sync();   // B1: all acts (X + dY + dh0) + partials complete
398	
399	    // ── P2: assemble all 28 grads. 8 projection dW output-stationary (gt %
400	    //    nCTA), dt_proj.bias, non-GEMM partial-reduce, embedding owner-scan. ──
401	    if (threadIdx.x == 0) mbtc::mbtc_build_dw_specs(acts, T, sm.spec);
402	    __syncthreads();
403	    mbtc::MbDwSpec* spec = sm.spec;
404	    const int n_dw = mbtc::mbtc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
405	    for (int gt = cta; gt < n_dw; gt += nCTA)
406	        mbtc::mbtc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
407	    mbtc::mbtc_dw_biases(spec, grad);
408	    mbtc::mbtc_partial_reduce(part_base, grad, nCTA, cta);
409	    mbtc::mbtc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
410	    // Loss reduce (fp64 ordered) by CTA 0.
411	    if (cta == 0 && threadIdx.x == 0) {
412	        double s = 0.0;
413	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
414	        *tok.loss_out = (float)(s / (double)B);
415	    }
416	    (void)loss_out;
417	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
418	
419	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal 28). ──
420	    st.lr = lr;
421	    {
422	        __shared__ int task_slot;
423	        TaskQueue q = ctx.queue();
424	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
425	             t = q.next_block(&task_slot)) {
426	            const int n = kMambaSizes[t];
427	            const int64_t off = (int64_t)kMambaOffsets[t];
428	            const FusedOptState ts = mamba_rebase_state<Opt>(st, off);
429	            float* __restrict__ p = params + off;
430	            const float* __restrict__ gg = grad + off;
431	            for (int i = threadIdx.x; i < n; i += blockDim.x)
432	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
433	        }
434	    }
435	}
