891	// ════════════════════════════════════════════════════════════════════════
892	//  P2 — OUTPUT-STATIONARY dW (the 4 projections × kLayers = 8 weight matrices,
893	//  dW = dYᵀ @ X, K=T). Each split into 64×N output tiles; tile_id % nCTA owns
894	//  each, contracting the FULL T (ascending-t, no atomics, no partials) via the
895	//  validated dW orientation (both operands transposed-staged, MaxAtomsM=1).
896	//  Writes into `grad`. The ONLY GEMM bias is dt_proj.bias = Σ_T ddt_pre.
897	//
898	//  The 8 weights, in named_parameters() tensor-index order:
899	//    L0: in_w=4, x_proj_w=7, dt_proj_w=8, out_w=10
900	//    L1: in_w=15, x_proj_w=18, dt_proj_w=19, out_w=21
901	//  with (dY, X) acts and Nout/Kin per the forward projection.
902	// ════════════════════════════════════════════════════════════════════════
903	// (still in namespace mbtc — opened above)
904	
905	struct MbDwSpec {
906	    const __nv_bfloat16* dY;   // [T, Nout]
907	    const __nv_bfloat16* X;    // [T, Kin]
908	    int Nout; int Kin; int T;
909	    int grad_off;
910	    bool has_bias;             // only dt_proj
911	    const __nv_bfloat16* dY_bias;
912	    int bias_off;
913	};
914	
915	// Build the 8 specs (cheap; all CTAs). T = B*kSeq.
916	__device__ __forceinline__ void mbtc_build_dw_specs(
917	        const MbActs& acts, int T, MbDwSpec spec[8]) {
918	    // per-layer tensor indices (and dt bias idx). L0 base=2 (tok=0,pos=1), 11/layer.
919	    for (int li = 0; li < mb::kLayers; ++li) {
920	        const int base = 2 + li * 11;
921	        const int in_w = base + 2, xp_w = base + 5, dt_w = base + 6, dt_b = base + 7, out_w = base + 8;
922	        MbDwSpec& s_in = spec[li * 4 + 0];
923	        s_in.dY = acts.dY_dxz[li];   s_in.X = acts.X_in[li];
924	        s_in.Nout = 2 * mb::kDInner; s_in.Kin = mb::kD; s_in.T = T;
925	        s_in.grad_off = kMambaOffsets[in_w]; s_in.has_bias = false;
926	        MbDwSpec& s_xp = spec[li * 4 + 1];
927	        s_xp.dY = acts.dY_dxdbc[li]; s_xp.X = acts.X_xmain[li];
928	        s_xp.Nout = mb::kDbc; s_xp.Kin = mb::kDInner; s_xp.T = T;
929	        s_xp.grad_off = kMambaOffsets[xp_w]; s_xp.has_bias = false;
930	        MbDwSpec& s_dt = spec[li * 4 + 2];
931	        s_dt.dY = acts.dY_ddtpre[li]; s_dt.X = acts.X_dtraw[li];
932	        s_dt.Nout = mb::kDInner; s_dt.Kin = mb::kDtRank; s_dt.T = T;
933	        s_dt.grad_off = kMambaOffsets[dt_w]; s_dt.has_bias = true;
934	        s_dt.dY_bias = acts.dY_ddtpre[li]; s_dt.bias_off = kMambaOffsets[dt_b];
935	        MbDwSpec& s_out = spec[li * 4 + 3];
936	        s_out.dY = acts.dY_dyout[li]; s_out.X = acts.X_ygated[li];
937	        s_out.Nout = mb::kD; s_out.Kin = mb::kDInner; s_out.T = T;
938	        s_out.grad_off = kMambaOffsets[out_w]; s_out.has_bias = false;
939	    }
940	}
