942	template <int N>
943	__device__ __forceinline__ int mbtc_dw_total_tiles(const MbDwSpec spec[8]) {
944	    int n = 0;
945	    for (int s = 0; s < 8; ++s)
946	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
947	    return n;
948	}
