950	// Run ONE global dW tile gt (if owned): dW = dYᵀ @ X, contract K=T. Both operands
951	// transposed-staged. K=T is a multiple of 16 (host enforces B%16==0 → T=B·8).
952	template <int N>
953	__device__ __forceinline__ void mbtc_dw_run_tile(
954	        const MbDwSpec spec[8], int gt, float* __restrict__ grad,
955	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
956	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
957	    for (s = 0; s < 8; ++s) {
958	        const int ma = (spec[s].Nout + 63) / 64;
959	        const int nt = (spec[s].Kin + N - 1) / N;
960	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
961	        acc += ma * nt;
962	    }
963	    const MbDwSpec& sp = spec[s];
964	    const int mbase = m_atom * 64;
965	    const int n0 = n_tile * N;
966	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
967	    const int k_steps = sp.T / wgs::kWgmmaAtomK;
968	    const int Nout = sp.Nout, Kin = sp.Kin;
969	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
970	    // A[m=out, k=t] = dY[t,out] (transposed); B[n=in, k=t] = X[t,in] (transposed).
971	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
972	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
973	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
974	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
975	    auto out  = [&] (int m, int n, float v) {
976	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
977	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
978	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
979	}
980	
981	// dt_proj.bias db = Σ_T ddt_pre (the ONLY GEMM bias). Each CTA strides all bias
982	// outputs (cheap: d_inner=256 rows × kLayers). Single owner per element.
983	__device__ __forceinline__ void mbtc_dw_biases(
984	        const MbDwSpec spec[8], float* __restrict__ grad) {
985	    for (int s = 0; s < 8; ++s) {
986	        const MbDwSpec& sp = spec[s];
987	        if (!sp.has_bias) continue;
988	        for (int o = threadIdx.x; o < sp.Nout; o += blockDim.x) {
989	            float accv = 0.0f;
990	            for (int k = 0; k < sp.T; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
991	            grad[sp.bias_off + o] = accv;
992	        }
993	    }
994	}
995	
996	// ════════════════════════════════════════════════════════════════════════
997	//  P2 — NON-GEMM grad reduce (A_log, D, conv_w/b, n_w/b per layer + head
998	//  norm_w/b, out_w/b). Each was accumulated tile-local into the per-CTA partial
999	//  [kPartElems]; sum across CTAs in ASCENDING CTA index (deterministic) into the
1000	//  named_parameters() slots of grad. `part_base` = start of [nCTA × kPartElems].
1001	//  Work split round-robin over the kPartElems by FLAT element (each element c is
1002	//  owned by cta = (global_flat_index / chunk)?) — simplest deterministic split:
1003	//  CTA strides the kPartElems by tensor (round-robin tensors), summing each
1004	//  tensor's elements across CTAs. We enumerate the (tensor-index, partial-slot,
1005	//  numel) triples and round-robin them by CTA.
1006	// ════════════════════════════════════════════════════════════════════════
1007	// Number of partial tensors to reduce: 6/layer + 4 head.
1008	constexpr int kNumPartTensors = mb::kLayers * 6 + 4;
1009	
1010	// Fill the (grad tensor index, partial-offset-in-CTA-slab, numel) for slot v.
1011	__device__ __forceinline__ void mbtc_part_slot(
1012	        int v, int& grad_idx, int64_t& part_off, int& numel) {
1013	    // per-layer order: A_log, D, conv_w, conv_b, n_w, n_b (6); head: norm_w,norm_b,out_w,out_b.
1014	    const int kLayerNumels[6] = {
1015	        mb::kDInner * mb::kState, mb::kDInner, mb::kDInner * mb::kConvK, mb::kDInner, mb::kD, mb::kD };
1016	    if (v < mb::kLayers * 6) {
1017	        const int li = v / 6, kind = v % 6;
1018	        const int base = 2 + li * 11;
1019	        const int tidx[6] = { base + 0, base + 1, base + 3, base + 4, base + 9, base + 10 };  // A_log,D,conv_w,conv_b,n_w,n_b
1020	        grad_idx = tidx[kind];
1021	        // partial offset within a CTA slab:
1022	        int64_t off = (int64_t)li * kPartPerLayer;
1023	        for (int k = 0; k < kind; ++k) off += kLayerNumels[k];
1024	        part_off = off; numel = kLayerNumels[kind];
1025	    } else {
1026	        const int h = v - mb::kLayers * 6;   // 0..3: norm_w,norm_b,out_w,out_b
1027	        const int htidx[4] = { 2 + mb::kLayers * 11 + 0, 2 + mb::kLayers * 11 + 1,
1028	                               2 + mb::kLayers * 11 + 2, 2 + mb::kLayers * 11 + 3 };
1029	        const int hnum[4] = { mb::kD, mb::kD, mb::kPHead * mb::kD, mb::kPHead };
1030	        grad_idx = htidx[h];
1031	        int64_t off = (int64_t)mb::kLayers * kPartPerLayer;
1032	        for (int k = 0; k < h; ++k) off += hnum[k];
1033	        part_off = off; numel = hnum[h];
1034	    }
1035	}
1036	
1037	__device__ __forceinline__ void mbtc_partial_reduce(
1038	        const float* __restrict__ part_base, float* __restrict__ grad,
1039	        int nCTA, int cta) {
1040	    for (int v = cta; v < kNumPartTensors; v += nCTA) {
1041	        int grad_idx, numel; int64_t part_off;
1042	        mbtc_part_slot(v, grad_idx, part_off, numel);
1043	        const int64_t gbase = kMambaOffsets[grad_idx];
1044	        for (int i = threadIdx.x; i < numel; i += blockDim.x) {
1045	            float accv = 0.0f;
1046	            for (int c = 0; c < nCTA; ++c)
1047	                accv += part_base[(int64_t)c * kPartElems + part_off + i];
1048	            grad[gbase + i] = accv;
1049	        }
1050	    }
1051	}
1052	
1053	// ════════════════════════════════════════════════════════════════════════
1054	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1055	//    tok grad row r (token id) → owner CTA (r % nCTA), scans ALL T tokens
1056	//    ascending-t accumulating dh0[t,:] for ids == r. pos row p → owner, sums
1057	//    dh0[t,:] over t with (t%S)==p. Fixed t-order + single owner → deterministic.
1058	// ════════════════════════════════════════════════════════════════════════
1059	__device__ __forceinline__ void mbtc_embed_owner_scan(
1060	        const MbActs& acts, const int* __restrict__ tok_ids, int T,
1061	        float* __restrict__ grad, int cta, int nCTA) {
1062	    const int tok_off = kMambaOffsets[0];
1063	    const int pos_off = kMambaOffsets[1];
1064	    for (int r = cta; r < mb::kVocab; r += nCTA) {
1065	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1066	            float accv = 0.0f;
1067	            for (int t = 0; t < T; ++t)
1068	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * mb::kD + j]);
1069	            grad[tok_off + (int64_t)r * mb::kD + j] = accv;
1070	        }
1071	    }
1072	    for (int p = cta; p < mb::kSeq; p += nCTA) {
1073	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1074	            float accv = 0.0f;
1075	            for (int t = 0; t < T; ++t)
1076	                if ((t % mb::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * mb::kD + j]);
1077	            grad[pos_off + (int64_t)p * mb::kD + j] = accv;
1078	        }
1079	    }
1080	}
1081	
1082	}  // namespace mbtc
1083	
1084	}}} // namespace sg::fused::sm90
