42	// Persistent barrier/queue counters + the TC workspace, cached per device.
43	struct TcScratch {
44	    torch::Tensor g_next, g_arrived, g_generation, workspace;
45	    int n_ctas = 0;
46	    int64_t ws_floats = 0;
47	};
48	
49	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
50	    int dev = params.get_device();
51	    int n_sms = 1;
52	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
53	    int n = n_sms;
54	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
55	    return n;
56	}
57	
58	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
59	    static TcScratch s;
60	    const int T = B * mb::kSeq;
61	    const int64_t need = ::sg::fused::sm90::mb_tc_workspace_floats(T, nCTA);
62	    if (!s.g_next.defined()) {
63	        auto opt_i = torch::dtype(torch::kInt32).device(params.device());
64	        s.g_next = torch::zeros({1}, opt_i);
65	        s.g_arrived = torch::zeros({1}, opt_i);
66	        s.g_generation = torch::zeros({1}, opt_i);
67	    }
68	    s.n_ctas = nCTA;
69	    if (s.ws_floats < need) {
70	        auto opt_f = torch::dtype(torch::kFloat32).device(params.device());
71	        s.workspace = torch::empty({need}, opt_f);
72	        s.ws_floats = need;
73	    }
74	    return s;
75	}
76	
77	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
78	// tokens [B,kSeq] int32; targets [B] int32; state [3*total] fp32 ([m|v|extra]).
79	// Returns {loss (cpu float scalar), grad [total] fp32 (the reduced grad)}.
80	static std::vector<torch::Tensor> tc_train_step(
81	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
82	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
83	        double weight_decay, double bc1, double bc2, int64_t step,
84	        int64_t ncta_cap) {
85	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
86	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
87	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
88	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
89	    const int B = (int)targets.numel();
90	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
91	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
92	    const int64_t total = kMambaTotalElems;
93	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
94	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
95	
96	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
97	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
98	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
99	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
100	
101	    PersistentContext ctx{
102	        sc.g_next.data_ptr<int>(),
103	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
104	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
105	        ::sg::fused::sm90::kMambaNumTensors,
106	        0u};
107	
108	    FusedOptState st;
109	    float* m = state.data_ptr<float>();
110	    st.exp_avg = m;
111	    st.exp_avg_sq = m + total;
112	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
113	    st.eps = (float)eps; st.wd = (float)weight_decay;
114	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
115	
116	    MambaTokenCtx tok;
117	    tok.tokens = tokens.data_ptr<int>();
118	    tok.targets = targets.data_ptr<int>();
119	    tok.B = B;
120	    tok.workspace = sc.workspace.data_ptr<float>();
121	    tok.loss_out = loss_dev.data_ptr<float>();
122	
123	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
124	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel_tc<OptId::AdamW>(
125	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
126	        (float)lr, (int)step, st, stream, nCTA);
127	    TORCH_CHECK(err == cudaSuccess, "TC mamba megakernel launch failed: ", cudaGetErrorString(err));
128	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
129	
130	    return {loss_dev.to(torch::kCPU), grad};
131	}
132	
133	// CALIBRATION HOOK (test_mamba_tc.py::test_tc_proj_dw_exact_on_own_operands):
134	// slice the kernel's OWN stored bf16 acts dY_dyout[L1] [T,d] and X_ygated[L1]
135	// [T,d_inner] from the workspace, returned as fp32 CPU tensors. The gate
136	// contracts them in fp32 ascending-t and compares to the kernel's
137	// out_proj.weight grad slice — isolating the output-stationary dW GEMM (K=T)
138	// from the operand-chain bf16 divergence. A ~1e-6 match proves the dW GEMM is
139	// bit-exact on its own operands, calibrating the per-tensor bf16 tol as headroom
140	// over a GEMM-exact floor. Reuses the cached workspace (call AFTER tc_train_step).
141	static std::vector<torch::Tensor> tc_dump_outproj_operands(torch::Tensor params, int64_t B) {
142	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
143	    const int T = (int)B * mb::kSeq;
144	    auto acts_bf16 = sc.workspace.slice(0, 0, mbtc::mb_acts_floats(T)).view(torch::kBFloat16);
145	    // walk mb_acts_bind to dY_dyout[1] and X_ygated[1].
146	    const int64_t d = mb::kD, di = mb::kDInner, dr = mb::kDtRank, dbc = mb::kDbc;
147	    const int64_t Td = (int64_t)T * d, Tdi = (int64_t)T * di, Tdr = (int64_t)T * dr,
148	                  Tdbc = (int64_t)T * dbc, T2di = (int64_t)T * 2 * di;
149	    int64_t off = 0, off_Xyg1 = -1, off_dYout1 = -1;
150	    for (int li = 0; li < mb::kLayers; ++li) {
151	        off += Td;            // X_in
152	        off += Tdi;           // X_xmain
153	        off += Tdr;           // X_dtraw
154	        if (li == 1) off_Xyg1 = off;
155	        off += Tdi;           // X_ygated
156	        off += T2di;          // dY_dxz
157	        off += Tdbc;          // dY_dxdbc
158	        off += Tdi;           // dY_ddtpre
159	        if (li == 1) off_dYout1 = off;
160	        off += Td;            // dY_dyout
161	    }
162	    auto dYout1 = acts_bf16.slice(0, off_dYout1, off_dYout1 + Td).to(torch::kFloat32).to(torch::kCPU);
163	    auto Xyg1 = acts_bf16.slice(0, off_Xyg1, off_Xyg1 + Tdi).to(torch::kFloat32).to(torch::kCPU);
164	    return {dYout1, Xyg1};   // [T*d], [T*d_inner]
165	}
166	
167	// scalar_train_step: the SAME (mamba × AdamW) cell run through the SCALAR default
168	// launcher (launch_fused_mamba_megakernel<AdamW>, OUTSIDE the wgmma guard — this
169	// wgmma-token TU can still call it). For the step-time gate to time scalar and TC
170	// back-to-back in one process / one contention regime → an honest scalar:TC ratio.
171	// The scalar path uses its OWN workspace (nCTA*total partials + nCTA loss + 1).
172	// NOT the shipped invocation (that is dispatch.cpp via mega_mamba_real_adamw.cu);
173	// a measurement mirror. Returns {loss, reduced grad}. NOTE: the scalar mamba
174	// kernel needs ~142KB DYNAMIC smem (its launcher does the opt-in internally).
175	static std::vector<torch::Tensor> scalar_train_step(
176	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
177	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
178	        double weight_decay, double bc1, double bc2, int64_t step) {
179	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
180	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
181	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
182	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
183	    const int B = (int)targets.numel();
184	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
185	    const int64_t total = kMambaTotalElems;
186	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
187	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
188	
189	    int dev = params.get_device();
190	    int n_sms = 1;
191	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
192	
193	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
194	    static int64_t s_ws_floats = 0;
195	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
196	    if (!s_gn.defined()) {
197	        auto oi = torch::dtype(torch::kInt32).device(params.device());
198	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
199	    }
200	    if (s_ws_floats < need) {
201	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
202	        s_ws_floats = need;
203	    }
204	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
205	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
206	
207	    PersistentContext ctx{
208	        s_gn.data_ptr<int>(),
209	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
210	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
211	        ::sg::fused::sm90::kMambaNumTensors, 0u};
212	
213	    FusedOptState st;
214	    float* m = state.data_ptr<float>();
215	    st.exp_avg = m; st.exp_avg_sq = m + total;
216	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
217	    st.eps = (float)eps; st.wd = (float)weight_decay;
218	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
219	
220	    MambaTokenCtx tok;
221	    tok.tokens = tokens.data_ptr<int>();
222	    tok.targets = targets.data_ptr<int>();
223	    tok.B = B;
224	    tok.workspace = s_ws.data_ptr<float>();
225	    tok.loss_out = loss_out;
226	
227	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
228	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel<OptId::AdamW>(
229	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
230	        (float)lr, (int)step, st, stream);
231	    TORCH_CHECK(err == cudaSuccess, "scalar mamba megakernel launch failed: ", cudaGetErrorString(err));
232	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
233	
234	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
235	                        .to(torch::kCPU);
236	    return {loss_cpu, grad};
237	}
