251	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
252	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
253	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
254	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"));
255	    mm.attr("TILE_M") = (int)mbtc::kTileM;
256	    mm.attr("TILE_N") = (int)SG_TUNED_TILE_N;
257	    mm.attr("TOTAL") = (int)kMambaTotalElems;
