// For each stacked atom (M-base = mbase0 + a*64), run the full k-chain.
#pragma unroll 1
for (int a = 0; a < m_atoms; ++a) {
    const int mbase = mbase0 + a * wgs::kWgmmaAtomM;
    // Prologue: stage tile 0; make visible; fence.
    stage_k(mbase, 0);
    __syncthreads();
    if (in_wg0) wgs::wgmma_fence();
