182	// Dispatch to the REAL per-element optimizer step. Each branch is a genuine,
183	// distinct call into csrc/algorithms/<opt>.h — there is no AdamW fallback.
184	template <OptId Opt>
185	__device__ __forceinline__ void apply_optimizer(
186	        float* __restrict__ params, const float* __restrict__ grad,
187	        int64_t idx, int step, const FusedOptState& st) {
188	    (void)step;  // referenced only by the cold-start branches (grokfast/grokadamw)
189	    if constexpr (Opt == OptId::AdamW) {
190	        algo::adamw_step<float, float>(
191	            params, st.exp_avg, st.exp_avg_sq, grad,
192	            st.lr, st.beta1, st.beta2, st.eps, st.wd, st.bc1, st.bc2, idx);
193	    } else if constexpr (Opt == OptId::Lion) {
194	        algo::lion_step<float, float>(
195	            params, st.exp_avg, grad, st.lr, st.beta1, st.beta2, st.wd, idx);
196	    } else if constexpr (Opt == OptId::Grokfast) {
197	        // COLD-START (state-aware tail; owner baseline blocker (a)): the eager
198	        // Grokfast seeds the slow-grad EMA with the FIRST gradient, not zeros
199	        // (grokfast.py _group_cache: state["ema"] = grad0.clone()), because a
200	        // zero seed under-amplifies the early grokking phase and the kernel
201	        // applies no EMA bias correction. The persistent [m|v|extra] state cache
202	        // zero-inits ema=0, so at step 1 we must seed ema=grad HERE — then
203	        // grokfast_fused_step's e_new = alpha*g + (1-alpha)*g = g matches the
204	        // eager ema=grad0 exactly. Per-element on this thread's own idx (the P3
205	        // tail owns each element once), so no race / no barrier needed. For
206	        // step>1 the cache carries the real EMA forward (no reseed).
207	        if (step == 1) st.ema[idx] = grad[idx];
208	        algo::grokfast_fused_step<float, float>(
209	            params, st.exp_avg, st.exp_avg_sq, st.ema, grad,
210	            st.alpha, st.lamb, st.lr, st.beta1, st.beta2, st.eps, st.wd,
211	            st.bc1, st.bc2, idx);
212	    } else if constexpr (Opt == OptId::GrokAdamW) {
213	        // COLD-START (same as Grokfast: eager GrokAdamW seeds ema=grad0 —
214	        // grokadamw.py _group_cache). Seed ema=grad at step 1 so e_new collapses
215	        // to g, matching eager. NOTE: this is necessary-but-NOT-sufficient for a
216	        // faithful GrokAdamW conversion — eager ALSO applies (i) per-tensor
217	        // layer-wise beta1 = beta1*(1-gamma)^layer and (ii) a per-tensor
218	        // grad-norm clip to grad_clip (bindings.cpp clip_grad_norms_device_side)
219	        // BEFORE this apply. Those two need a per-tensor scalar side-channel +
220	        // a P3 norm reduction; until both land, GrokAdamW stays BLOCKED (not
221	        // registered in _FUSED_L3_REAL). The cold-start is staged here so the
222	        // remaining gap is exactly (i)+(ii).
223	        if (step == 1) st.ema[idx] = grad[idx];
224	        algo::grokadamw_step<float, float>(
225	            params, st.exp_avg, st.exp_avg_sq, st.ema, grad,
226	            st.alpha, st.lamb, st.lr, st.beta1, st.beta2, st.eps, st.wd,
227	            st.bc1, st.bc2, idx);
228	    } else if constexpr (Opt == OptId::LookSAM) {
229	        algo::looksam_apply_step<float, float>(
230	            params, st.exp_avg, st.exp_avg_sq, st.sam_dir, grad,
231	            st.alpha, st.lr, st.beta1, st.beta2, st.eps, st.wd,
232	            st.bc1, st.bc2, idx);
233	    } else if constexpr (Opt == OptId::Prodigy) {
234	        algo::prodigy_apply_step<float, float>(
235	            params, st.exp_avg, st.exp_avg_sq, st.s_track, grad,
236	            st.d_factor, st.beta1, st.beta2, st.eps, st.wd,
237	            st.bc1, st.bc2, idx);
238	    } else if constexpr (Opt == OptId::NeuralGrok) {
239	        // psi_b2 is the scalar packed immediately after psi_W2 in the `extra`
240	        // buffer (extra[kPsiB2Off] == st.psi_W2[kPsiHidden]). Read it ON-DEVICE
241	        // here, where the pointer is dereferenceable — the host cell cannot
242	        // deref a device pointer, so it leaves st.psi_b2 at its 0.0f default.
243	        // This threads the real psi_b2 bias (previously stuck at 0.0).
244	        const float psi_b2 = (st.psi_W2 != nullptr) ? st.psi_W2[kPsiHidden]
245	                                                     : st.psi_b2;
246	        const float psi = algo::neuralgrok_psi_forward<kPsiHidden>(
247	            fabsf(grad[idx]), st.psi_W1, st.psi_b1, st.psi_W2, psi_b2);
248	        algo::neuralgrok_apply_step<float, float>(
249	            params, st.exp_avg, st.exp_avg_sq, grad, psi,
250	            st.alpha, st.beta, st.lr, st.beta1, st.beta2, st.eps, st.wd,
251	            st.bc1, st.bc2, idx);
252	    } else if constexpr (Opt == OptId::Muon) {
253	        // 2D params: NS-orthogonalized direction precomputed; tail is the
254	        // momentum-decayed scaled apply. (1D params use AdamW upstream.)
255	        algo::muon_update_step<float>(
256	            params, st.orth, st.neg_lr_scale, st.decay_factor, idx);
257	    } else if constexpr (Opt == OptId::SuperGrok11) {
258	        algo::sg11_sweep_b_step<float, float>(
259	            params, st.exp_avg, st.exp_avg_sq, grad, st.mu, st.gate,
260	            st.alpha, st.lr, st.beta1, st.beta2, st.eps, st.wd,
261	            st.bc1, st.bc2, idx);
262	    } else if constexpr (Opt == OptId::SuperGrok15) {
263	        algo::sg15_sweep_b_step<float, float>(
264	            params, st.exp_avg, st.exp_avg_sq, grad, st.mu, st.gate,
265	            st.alpha, st.alpha_max, st.lr, st.beta1, st.beta2, st.eps, st.wd,
266	            st.bc1, st.bc2, idx);
267	    } else {  // OptId::SuperGrok2 — Adam apply on the meta-net smart gradient.
268	        // The CSA/HCA+PEER meta-net (separate launch) produced st.smart_grad;
269	        // the fused tail is the real Adam apply on it (faithful to the per-op
270	        // SG2 path's apply stage).
271	        const float* g = (st.smart_grad != nullptr) ? st.smart_grad : grad;
272	        algo::adamw_step<float, float>(
273	            params, st.exp_avg, st.exp_avg_sq, g,
274	            st.lr, st.beta1, st.beta2, st.eps, st.wd, st.bc1, st.bc2, idx);
275	    }
276	}
