206	// ── Device-side gradient clipping: single CPU sync instead of N ──────
207	inline void clip_grad_norms_device_side(
208	    std::vector<torch::Tensor>& grads,
209	    size_t n_params,
210	    float grad_clip_norm
211	) {
212	    if (grad_clip_norm <= 0.0f) return;
213	
214	    // Collect the present grads once. Fused multi-tensor ops want a flat list.
215	    std::vector<torch::Tensor> present;
216	    present.reserve(n_params);
217	    for (size_t i = 0; i < n_params; i++) {
218	        if (grads[i].defined() && grads[i].numel() > 0)
219	            present.push_back(grads[i]);
220	    }
221	    if (present.empty()) return;
222	
223	    // Per-tensor L2 norms via a single fused multi-tensor reduction
224	    // (torch::_foreach_norm), replacing the per-tensor upcast + dot + add_
225	    // (≈2N kernel launches) with one foreach launch. Numerics: the L2 norm of
226	    // each tensor is accumulated into a fp32 sum-of-squares (squaring the
227	    // per-tensor norm == that tensor's sum-of-squares), matching the original
228	    // fp32 accumulation of the global sum-of-squares. To preserve the original
229	    // precision when grads are NOT already fp32, upcast those (only) to fp32
230	    // before the norm; fp32 grads skip the upcast entirely.
231	    bool all_fp32 = true;
232	    for (auto& g : present)
233	        if (g.scalar_type() != torch::kFloat32) { all_fp32 = false; break; }
234	
235	    std::vector<torch::Tensor> norm_inputs;
236	    if (all_fp32) {
237	        norm_inputs = present;
238	    } else {
239	        norm_inputs.reserve(present.size());
240	        for (auto& g : present)
241	            norm_inputs.push_back(g.scalar_type() == torch::kFloat32
242	                                      ? g
243	                                      : g.to(torch::kFloat32));
244	    }
245	
246	    auto norms = torch::_foreach_norm(norm_inputs, /*p=*/2);
247	    // norm_sq = sum_i (||g_i||_2)^2, accumulated in fp32 on-device, one sync.
248	    auto stacked = torch::stack(norms).to(torch::kFloat32);
249	    float total_norm =
250	        std::sqrt(stacked.dot(stacked).item<float>());
251	
252	    if (total_norm > grad_clip_norm) {
253	        float clip_coef = grad_clip_norm / (total_norm + 1e-6f);
254	        // Fused multi-tensor in-place scale of the present grads.
255	        torch::_foreach_mul_(present, clip_coef);
256	    }
257	}
