259	// ── Device-side SAM grad-norm: single CPU sync instead of N ──────────
260	inline float compute_sam_grad_norm_device_side(
261	    std::vector<torch::Tensor>& grads,
262	    size_t n_grads
263	) {
264	    torch::Device dev(torch::kCPU);
265	    for (size_t i = 0; i < n_grads; i++) {
266	        if (grads[i].defined() && grads[i].numel() > 0) {
267	            dev = grads[i].device();
268	            break;
269	        }
270	    }
271	    auto norm_sq = torch::zeros(
272	        {1}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
273	    for (size_t i = 0; i < n_grads; i++) {
274	        if (grads[i].defined() && grads[i].numel() > 0) {
275	            auto g_flat = grads[i].to(torch::kFloat32).reshape(-1);
276	            norm_sq.add_(g_flat.dot(g_flat));
277	        }
278	    }
279	    return std::sqrt(norm_sq.item<float>()) + 1e-12f;
280	}
