388	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
389	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
390	    const int nrows_tile = dectc::kTileM;
391	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
392	    float nll_acc = 0.0f;
393	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
394	        const int g0 = ti * nrows_tile;
395	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
396	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
